{"code": "import os, re
os.chdir('/home/zhouhuijuan1987/wiki/youtube-video-research-wiki')
report_file = 'raw/notebooklm-analysis/krEDel3aGGw_f5e46b39-261e-4c52-92b3-c6125973b623_20260509T015450Z_report.md'
with open(report_file, 'r', encoding='utf-8') as f:
    content = f.read()

# Extract entities and concepts from the report
# Look for bold terms, section titles, etc.
# We'll do a simple extraction: look for terms in ** or specific patterns
entities = set()
concepts = set()

# Extract from bold text
bold_pattern = r'\*\*(.+?)\*\*'
for match in re.finditer(bold_pattern, content):
    term = match.group(1).strip()
    # Filter out common words
    if len(term) > 2 and term not in ['GPT-5.5 Instant', 'OpenAI', 'ChatGPT', 'API', '免费用户', '个人助理']:
        # Heuristic: if it's a product/model name or company
        if any(kw in term.lower() for kw in ['gpt', 'openai', 'chatgpt', 'api', '模型', '系统', '框架']):
            entities.add(term)
        else:
            concepts.add(term)

# Also extract from section titles
section_pattern = r'^##\s+(.+?)$'
for match in re.finditer(section_pattern, content, re.MULTILINE):
    term = match.group(1).strip()
    if '幻觉率' in term or '对话体验' in term or '记忆增强' in term or '数学推理' in term or '多模态能力' in term or 'API 策略' in term:
        concepts.add(term)

# Extract from key points bullet points
# Look for lines starting with -
for line in content.split('\n'):
    if line.strip().startswith('-'):
        # Extract bold terms from the line
        for match in re.finditer(bold_pattern, line):
            term = match.group(1).strip()
            if term:
                if '幻觉率' in term or '对话体验' in term or '记忆增强' in term or '数学推理' in term or '多模态' in term or 'API 策略' in term:
                    concepts.add(term)
                elif 'GPT-5.5' in term or 'OpenAI' in term or 'ChatGPT' in term:
                    entities.add(term)

print("Entities found:", entities)
print("Concepts found:", concepts)

# Also extract from the key quotes section
quotes_pattern = r'>\s+(.+?)$'
for match in re.finditer(quotes_pattern, content, re.MULTILINE):
    quote = match.group(1).strip()
    # Extract terms from quotes
    for match2 in re.finditer(bold_pattern, quote):
        term = match2.group(1).strip()
        if term:
            if 'AI 方向' in term or '说错' in term:
                concepts.add(term)
            elif '执行一个视频' in term:
                concepts.add(term)
            elif '过时的资料' in term:
                concepts.add(term)

print("After quotes:")
print("Entities found:", entities)
print("Concepts found:", concepts)"}

